    padding: 0.5rem 1rem;
    margin-bottom: 1.5rem;
}

.toggle-group .toggle-row:not(:last-child) {
    border-bottom: 1px solid #f0f0f0;
}

.toggle-switch {
    width: 2.5rem;
    height: 1.25rem;
    cursor: pointer;
}

/* Channel list */
.channel-section h3 {
    margin: 0 0 0.75rem;
    font-size: 1.1rem;
}

.channel-row {
    display: flex;
    align-items: center;
    gap: 0.5rem;
    padding: 0.4rem 0;
    cursor: pointer;
}

